import itertools
import random
import sys

sys.path.insert(0, "/home/c/brix2/a/task012")
import relay


def brute(nodes, links, flows, limit):
    cap = {(l["from"], l["to"]): l["bandwidth"] for l in links}
    adj = {n: [] for n in nodes}
    for l in links:
        if l["up"]:
            adj[l["from"]].append(l["to"])

    def all_paths(s, d):
        out = []
        stack = [(s, [s], {s})]
        while stack:
            u, p, seen = stack.pop()
            if u == d:
                out.append(p)
                continue
            for v in adj[u]:
                if v not in seen:
                    stack.append((v, p + [v], seen | {v}))
        return out

    cands = [all_paths(s, d) for _, s, d, b, _ in flows]
    edge = lambda p: list(zip(p, p[1:]))

    init_load = {}
    for _, s, d, b, p in flows:
        for e in edge(p):
            init_load[e] = init_load.get(e, 0) + b

    def peak(load):
        n, dd = 0, 1
        for e, u in load.items():
            c = cap[e]
            if u * dd > n * c:
                n, dd = u, c
        return n, dd

    i_n, i_d = peak(init_load)
    best = None
    for combo in itertools.product(*cands):
        moved = sum(1 for k in range(len(flows))
                    if combo[k] != flows[k][4])
        if moved > limit:
            continue
        load = {}
        ok = True
        for k, p in enumerate(combo):
            b = flows[k][3]
            for e in edge(p):
                load[e] = load.get(e, 0) + b
                if load[e] > cap[e]:
                    ok = False
                    break
            if not ok:
                break
        if not ok:
            continue
        n, dd = peak(load)
        if n * i_d >= i_n * dd:
            continue
        key = (n / dd, moved, combo)
        if best is None or key < best[0]:
            best = (key, combo, load, n, dd, moved)

    if best is None:
        return 0, i_n, i_d, 0, [(f[4], f[4]) for f in flows], init_load
    _, combo, load, n, dd, moved = best
    return 1, i_n, i_d, moved, [(flows[k][4], combo[k])
                                for k in range(len(flows))], load


def fmt(num, den):
    units = (2 * num * 1000000 + den) // (2 * den)
    return "%d.%06d" % (units // 1000000, units % 1000000)


