for trial in range(400):
    V = random.randint(2, 5)
    nodes = [chr(65 + i) for i in range(V)]
    E = random.randint(0, V * (V - 1))
    pairs = [(a, b) for a in nodes for b in nodes if a != b]
    random.shuffle(pairs)
    links = []
    for a, b in pairs[:E]:
        links.append({"from": a, "to": b,
                      "cost": random.randint(1, 5),
                      "up": random.random() < 0.8,
                      "bandwidth": random.randint(1, 8),
                      "latency": random.randint(0, 3)})
    # build feasible flows by picking reachable pairs and shortest edge path
    adj = {n: [] for n in nodes}
    for l in links:
        if l["up"]:
            adj[l["from"]].append(l["to"])

    def paths(s, d):
        out = []
        st = [(s, [s], {s})]
        while st:
            u, p, seen = st.pop()
            if u == d:
                out.append(p)
                continue
            for v in adj[u]:
                if v not in seen:
                    st.append((v, p + [v], seen | {v}))
        return out

    K = random.randint(0, 3)
    flows = []
    residual = {(l["from"], l["to"]): l["bandwidth"] for l in links}
    fi = 0
    tries = 0
    while fi < K and tries < 30:
        tries += 1
        s, d = random.sample(nodes, 2)
        ps = paths(s, d)
        if not ps:
            continue
        p = random.choice(ps)
        b = random.randint(1, 8)
