           "flows": [[flows[k][0], pairs_out[k][0], pairs_out[k][1]]
                     for k in range(len(flows))]}
    exp_links = {}
    for e, u in load.items():
        exp_links[e] = u
    exp["links"] = [[l["from"], l["to"], l["bandwidth"],
